// ClearContext clears the value of the "context" field.
func (u *BehavioralLogUpsertBulk) ClearContext() *BehavioralLogUpsertBulk {
	return u.Update(func(s *BehavioralLogUpsert) {
		s.ClearContext()
	})
}

// Exec executes the query.
func (u *BehavioralLogUpsertBulk) Exec(ctx context.Context) error {
	if u.create.err != nil {
		return u.create.err
	}
	for i, b := range u.create.builders {
		if len(b.conflict) != 0 {
			return fmt.Errorf("ent: OnConflict was set for builder %d. Set it on the BehavioralLogCreateBulk instead", i)
		}
	}
	if len(u.create.conflict) == 0 {
		return errors.New("ent: missing options for BehavioralLogCreateBulk.OnConflict")
	}
	return u.create.Exec(ctx)
}

// ExecX is like Exec, but panics if an error occurs.
func (u *BehavioralLogUpsertBulk) ExecX(ctx context.Context) {
	if err := u.create.Exec(ctx); err != nil {
		panic(err)
	}
}
